// Hyrule: entry point for hyrule.html. Fan work - The Legend of Zelda: Breath of the Wild and Hyrule belong to
// Nintendo; nothing from the game is used, and every shape is this project's own. The land, the roads and the plan
// are generated by tools/make-hyrule.py and drawn by the engine Chicago and Mordor share. The page brings the rest:
// the ground's colours and the water (paint.js), the castle, the towers, the shrines, the villages and the Divine
// Beasts (landmarks.js), what moves (life.js) and what happens (events.js).
import {report,LOAD,configureLoading,installErrorHandlers} from '../core/diag.js';
import {boot} from '../core/shell.js';
import {build} from '../engine/build.js';
import {sceneRows} from '../core/layout.js';
import {landmarks} from './landmarks.js';
import {beasts} from './beasts.js';
import {paint} from './paint.js';
import {flora} from './flora.js';
import {life} from './life.js';
import {events} from './events.js';
installErrorHandlers();window.LOAD=LOAD;
configureLoading({
  lines:[
    'Fan work. Breath of the Wild and Hyrule belong to Nintendo; every shape here is this project\'s own geometry.',
    'Open your eyes.',
    'Hyrule Castle stands in the middle of the country, and Calamity Ganon is coiled round it.',
    'The Great Plateau is a table of land walled by cliffs. The Temple of Time is on top of it.',
    'Fifteen Sheikah towers stand across the country. Climb one and the map fills in.',
    'Four Divine Beasts: Vah Ruta in Zora\'s Domain, Vah Rudania on Death Mountain, Vah Medoh over Rito Village, Vah Naboris in the Gerudo Desert.',
    'Death Mountain is a volcano; the Gorons live on its slopes.',
    'The shrines glow orange until they have been done, and blue after.',
    'The Lost Woods are in the Great Hyrule Forest, behind a ring of water. Don\'t lose your way.',
    'Every now and then the moon turns red.',
  ],
  prefix:'',labels:{'map-data':'reading the map',ground:'raising the land',buildings:'building the villages',details:'',
    landmarks:'raising the castle',el:'',traffic:'',ui:'opening the Sheikah Slate',paint:'painting the fields',flora:'planting the woods',life:'waking the guardians',events:'watching the sky'}});

function fingerprint(api){
  const {THREE,ctx,scene}=api;
  ctx.lotList=sceneRows(THREE,scene,{skip:o=>o.userData.noFingerprint||o.isSprite||o.isSky});
}

(async()=>{
  const C0=await fetch('data/cities/hyrule.json').then(r=>r.json()).catch(()=>({}));
  const plan=await fetch(C0.plan||'data/cities/hyrule-plan.json').then(r=>r.json()).catch(e=>{report('the plan',e);return null;});
  const ctx=window._iz={defaultCity:'hyrule',plan,models:[landmarks,beasts],
    extras:[{name:'paint',fn:paint},{name:'flora',fn:flora},{name:'life',fn:life},{name:'events',fn:events},{name:'fingerprint',fn:fingerprint}]};
  boot(()=>build(ctx));
})();
